import './Header.css';
import 'bootstrap/dist/css/bootstrap.min.css';
import React, { useRef, useEffect, useState, forwardRef } from "react";

const Header = forwardRef((props, ref) => {
  const [isHome, setIsHome] = useState(true);
  const homeRef = useRef(null); // référence à la section Home

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        // true si la section home est visible dans le viewport
        setIsHome(entry.isIntersecting);
      },
      {
        root: null,
        threshold: 0.1, // 10% de la section visible
      }
    );

    const homeSection = document.getElementById("home");
    if (homeSection) observer.observe(homeSection);

    return () => {
      if (homeSection) observer.unobserve(homeSection);
    };
  }, []);

	return (
    <div
      ref={ref} // <-- attacher le ref ici
      className={`${isHome ? "bg-dark-transparent" : "bg-dark"} container-fluid d-flex text-white justify-content-between align-items-center`}
      style={{
        minHeight: "10vh",
        position: "fixed",
        top: 0,
        left: 0,
        width: "100%",
        zIndex: 1000,
        paddingLeft: "200px",
        paddingRight: "200px",
		   transition: "background-color 0.3s ease",
      }}
    > 
      {/* Navbar collée en haut */}
      <nav className="navbar navbar-dark navbar-expand-lg w-100">
	  <a class="navbar-brand" href="#">
	  	<img src="/logo.png" alt="logo Agengemb" style={{ height: "8vh"}}/>
	  </a>
	<button
          className="navbar-toggler"
          type="button"
          data-bs-toggle="collapse"
          data-bs-target="#mainNavbar"
          aria-controls="mainNavbar"
          aria-expanded="false"
          aria-label="Toggle navigation"
        >
          <span className="navbar-toggler-icon"></span>
        </button>


	 <div id="mainNavbar" className="collapse navbar-collapse">
          <ul className="ms-auto navbar-nav flex-column flex-lg-row">
		<li className="nav-item">
            		<a href="#accueil" className="nav-link text-white">Accueil</a>
            	</li>
		<li className="nav-item">
	  	<a href="#apropos" className="nav-link text-white">À Propos</a>
          	</li>  

		<li className="nav-item">
	  	<a href="#projets" className="nav-link text-white">Projets</a>
          	</li>  
		<li className="nav-item">
	  <a href="#contact" className="nav-link text-white">Contact</a>
        	</li>
	  </ul>
	  </div>
      </nav>
    </div>
  );
});

export default Header;
